using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
// setup: an isolated structural foundation symbol and the lowest level
var symbol = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFoundation).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();
var level  = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var loc = new XYZ(40, 10, 0);

ElementId footId = null;
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    var foot = doc.Create.NewFamilyInstance(loc, symbol, level, StructuralType.Footing);
    footId = foot.Id;
});

var created = (FamilyInstance)doc.GetElement(footId);
return new { footId = footId.ToString(), symbol = symbol.Name, level = level.Name, structuralType = created.StructuralType.ToString(), category = created.Category?.Name };
